function traceView(t){const issues=t.integrityIssues||[];return `<div class="trace-card">${issues.length?panel('هشدار یکپارچگی شجره',table(['نوع','بچ مرتبط','والد مشکل‌دار','شدت'],issues.map(x=>`<tr><td>${esc(x.type)}</td><td class="mono">${esc(x.entityId)}</td><td class="mono">${esc(x.missingParentId||x.cycleParentId||'—')}</td><td>${status(x.severity)}</td></tr>`))):''}<div class="trace-root"><span>بچ فعلی</span><h3>${esc(t.batch.code)}</h3><p>${esc(t.batch.product)} · ${fa(t.batch.weightKg)} kg</p>${status(t.batch.status)}</div><div class="trace-lines">${t.ancestors.length?t.ancestors.map(a=>`<article><span>↑</span><div><b>${esc(a.code)}</b><small>${esc(a.process||'RECEIVING')} · ${fa(a.weightKg)} kg</small></div></article>`).join(''):empty('این بچ ورودی اولیه است')}</div><div class="two-col">${panel('اندازه‌گیری‌ها',table(['وزن','دلیل','زمان'],t.measurements.map(m=>`<tr><td>${fa(m.weightKg)} kg</td><td>${esc(m.reason)}</td><td>${dt(m.measuredAt)}</td></tr>`)))}${panel('جابه‌جایی‌ها',table(['از','به','زمان'],t.movements.map(m=>`<tr><td>${esc(m.from)}</td><td>${esc(m.to)}</td><td>${dt(m.movedAt)}</td></tr>`)))}</div></div>`}
async function cloudRequest(path){if(!CLOUD)throw Object.assign(Error('CLOUD_URL_NOT_CONFIGURED'),{code:'CLOUD_URL_NOT_CONFIGURED'});if(location.protocol==='https:'&&CLOUD.startsWith('http://'))throw Object.assign(Error('CLOUD_MIXED_CONTENT'),{code:'CLOUD_MIXED_CONTENT'});let response;try{response=await fetch(CLOUD+path,{headers:{'X-Cloud-Report-Key':cloudReportKey()}})}catch(cause){throw Object.assign(Error('CLOUD_NETWORK_ERROR'),{code:'CLOUD_NETWORK_ERROR',cause})}let payload={};try{payload=await response.json()}catch{}if(!response.ok)throw Object.assign(Error(payload.message||payload.errorCode||`Cloud HTTP ${response.status}`),{status:response.status,code:payload.errorCode||'CLOUD_HTTP_ERROR'});return payload}
function cloudErrorMessage(error){if(error.code==='CLOUD_URL_NOT_CONFIGURED')return 'اتصال Cloud تنظیم نشده است؛ آدرس و کلید گزارش را ثبت کنید.';if(error.code==='CLOUD_MIXED_CONTENT')return 'مرورگر اتصال HTTP به Cloud را از صفحه HTTPS مسدود می‌کند؛ آدرس HTTPS وارد کنید.';if(error.status===401)return 'کلید گزارش Cloud نامعتبر یا ثبت نشده است.';if(error.status>=500)return `سرویس Cloud با خطای ${error.status} پاسخ داد.`;return 'ارتباط شبکه با Cloud برقرار نشد؛ آدرس و دسترسی شبکه را بررسی کنید.'}
async function loadCloud(){try{const[health,summary]=await Promise.all([cloudRequest('/health'),cloudRequest('/api/summary')]);$('#cloudContent').innerHTML=`<div class="cloud-hero"><span>☁</span><div><h2>StoreMesh Cloud Control</h2><p>دید یکپارچه بدون دخالت در عملیات محلی سایت‌ها</p></div>${status(health.status==='ok'?'ACTIVE':'FAILED')}</div><div class="site-grid">${['IRAN','DUBAI','ROME'].map(s=>{const x=summary.sites?.[s]||{status:'PENDING'};return `<article><div><span class="flag">${{IRAN:'IR',DUBAI:'AE',ROME:'IT'}[s]}</span>${status(x.status||'PENDING')}</div><h3>${s}</h3><b>${fa(x.events||0)}</b><small>رویداد همگام‌شده</small><p>آخرین دریافت Cloud: ${dt(x.lastReceivedAt)}</p><p>آخرین رویداد کسب‌وکار: ${dt(x.lastSync)}</p></article>`}).join('')}</div>`}catch(error){$('#cloudContent').innerHTML=empty(cloudErrorMessage(error))}}
function exportInventory(){const rows=state.data.inventory?.items||[],csv=['code,product,grade,size,weightKg,zone,status',...rows.map(x=>[x.code,x.product,x.grade,x.size,x.weightKg,x.zone,x.status].join(','))].join('\n'),blob=new Blob([csv],{type:'text/csv'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='storemesh-inventory.csv';a.click();URL.revokeObjectURL(a.href)}
function downloadShipmentDocuments(id){const shipment=(state.data.shipments?.items||[]).find(x=>x.id===id),order=(state.data['sales-orders']?.items||[]).find(x=>x.id===shipment?.salesOrderId),customer=(state.data.customers?.items||[]).find(x=>x.id===shipment?.customerId),packages=(shipment?.packageIds||[]).map(pid=>(state.data.packages?.items||[]).find(x=>x.id===pid)).filter(Boolean),freshBoxes=(shipment?.shippingBoxIds||[]).map(bid=>(state.data['fresh-shipping-boxes']?.items||[]).find(x=>x.id===bid)).filter(Boolean),items=[...packages,...freshBoxes],scans=(state.data['shipment-carton-scans']?.items||[]).filter(x=>x.shipmentId===id);if(!shipment)return;const sections=[['Packing List',`Customer: ${esc(customer?.name)}<br>Order: ${esc(order?.code)}<br>Cartons: ${packages.length}<br>Fresh Shipping Boxes: ${freshBoxes.length}`],['Shipment Item List',items.map((x,i)=>`${i+1}. ${esc(x.code)} — ${esc(x.type||'CARTON')} — ${esc(x.status)}`).join('<br>')],['Shipment Summary',`Shipment: ${esc(shipment.code)}<br>Status: ${esc(shipment.status)}<br>Vehicle: ${esc(shipment.vehicle||'—')}<br>Expected: ${items.length} / Scanned: ${scans.length}`]],html=`<!doctype html><meta charset="utf-8"><title>${esc(shipment.code)}</title><style>body{font:16px Arial;padding:32px}section{page-break-after:always}h1{border-bottom:2px solid #222;padding-bottom:8px}</style>${sections.map(x=>`<section><h1>${x[0]}</h1><p>${x[1]}</p></section>`).join('')}`,blob=new Blob([html],{type:'text/html'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${shipment.code}-documents.html`;a.click();URL.revokeObjectURL(a.href)}

$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();try{const v=Object.fromEntries(new FormData(e.currentTarget)),r=await request('/api/auth/login',{method:'POST',body:JSON.stringify(v)});state.token=r.token;sessionStorage.token=r.token;$('#loginDialog').close();await loadData()}catch(err){$('#loginError').textContent=err.message}});
